package com.railflow.yardops.service;
import com.railflow.yardops.domain.*; import com.railflow.yardops.repository.*; import io.micrometer.core.instrument.simple.SimpleMeterRegistry; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import java.time.Instant; import java.util.Optional; import static org.mockito.Mockito.*; import static org.junit.jupiter.api.Assertions.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class EventIngestionServiceTest { @Mock ScanEventRepository events; @Mock RailcarRepository railcars; @Mock AlertRepository alerts; @Test void persistsEventAndUpdatesKnownRailcar(){var event=new ScanEvent("BNSF-1","NPT","ARRIVAL",Instant.now());var car=new Railcar("BNSF-1","Boxcar",100,"KCM","Paper",RailcarStatus.IN_TRANSIT);when(events.save(any())).thenReturn(event);when(railcars.findByCarNumber("BNSF-1")).thenReturn(Optional.of(car));var service=new EventIngestionService(events,railcars,alerts,new AlertRuleEngine(),new SimpleMeterRegistry());assertSame(event,service.ingest(event));assertEquals("NPT",car.getLocation());verify(events).save(event);verifyNoInteractions(alerts);}}